#!/usr/bin/env node
// Generated by ai-factory. PreToolUse path guard.
// Reads factory-scope.json (next to this file):
//   { "forbidden": [globs], "agents": { "<agent>": [allow globs] } }
// Usage: node factory-guard.mjs [agentName]
//   - always blocks edits matching a forbidden glob (relative path or basename)
//   - if agentName has an allow-list, blocks edits whose relative path matches none of it
// Do not hand-edit — edit .factory.yaml and re-run `factory install`.
import { readFileSync, realpathSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, basename, join, resolve, relative } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
let config = { forbidden: [], agents: {} };
try { config = JSON.parse(readFileSync(join(here, "factory-scope.json"), "utf8")); } catch {}

function globToRegExp(glob) {
  let re = "";
  let inBrace = false;
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === "*") {
      if (glob[i + 1] === "*") {
        re += ".*";
        i++;
        if (glob[i + 1] === "/") i++;
      } else {
        re += "[^/]*";
      }
    } else if (c === "?") {
      re += "[^/]";
    } else if (c === "{") {
      re += "(";
      inBrace = true;
    } else if (c === "}") {
      re += ")";
      inBrace = false;
    } else if (c === "," && inBrace) {
      re += "|";
    } else if (".+^$()|[]\\".includes(c)) {
      re += "\\" + c;
    } else {
      re += c;
    }
  }
  return new RegExp("^" + re + "$");
}

let raw = "";
try { raw = readFileSync(0, "utf8"); } catch {}
let data = {};
try { data = JSON.parse(raw || "{}"); } catch {}
if (!data || typeof data !== "object") data = {};

// Which agent is acting, in order of trust:
//   1. argv[2] — an explicit name, used by platforms that can pass one per agent
//      (Kiro CLI puts it in each agent's own hook command).
//   2. `agent_type` in the PreToolUse payload — the acting subagent's name, or
//      null when the main session is editing. This is how Claude Code reports it
//      to a single session-wide hook, which is the only kind that actually runs
//      there: per-agent hooks declared in agent frontmatter are silently ignored
//      (verified against Claude Code 2.1.278 — only the settings.json hook fired,
//      and it fired with no argv).
// An unknown agent leaves `allow` null, so only the forbidden list applies.
const agentName = process.argv[2] || (typeof data.agent_type === "string" ? data.agent_type : "") || "";
const forbidden = (config.forbidden || []).map((g) => ({ g, re: globToRegExp(g) }));
const allowGlobs = agentName && config.agents && config.agents[agentName] ? config.agents[agentName] : null;
const allow = allowGlobs ? allowGlobs.map((g) => ({ g, re: globToRegExp(g) })) : null;

const ti = data.tool_input || {};
const filePath = ti.file_path || ti.notebook_path || ti.path || "";
if (!filePath) process.exit(0);

// Resolve symlinks before matching. resolve() is purely lexical, so without this
// a symlink sitting inside an allowed directory (src/services/leak.ts -> ../../.env)
// would be matched by its link path and sail past the forbidden list. realpath()
// throws when the target doesn't exist yet — which is the normal case for a Write —
// so fall back to the deepest ancestor that does exist and re-append the rest.
function realPath(abs) {
  try { return realpathSync(abs); } catch {}
  let dir = dirname(abs);
  const tail = [basename(abs)];
  for (;;) {
    try { return join(realpathSync(dir), ...tail.slice().reverse()); } catch {}
    const parent = dirname(dir);
    if (parent === dir) return abs; // reached the root with nothing resolvable
    tail.push(basename(dir));
    dir = parent;
  }
}

// Normalize to a repo-relative POSIX path. resolve()+relative() collapse '..',
// '.', and '//' so traversal can't smuggle an out-of-scope path past a glob,
// and a sibling dir whose name merely shares cwd's prefix isn't mis-sliced.
// Both sides go through realPath so they agree on symlinked roots (on macOS
// /tmp and /var are themselves symlinks, so comparing one raw against one
// resolved would yield a bogus '../..' relative path).
const cwd = data.cwd || process.cwd();
let rel = relative(realPath(cwd), realPath(resolve(cwd, String(filePath))));
rel = rel.split("\\").join("/");
const base = rel.split("/").pop() || rel;

for (const f of forbidden) {
  if (f.re.test(rel) || f.re.test(base)) {
    console.error('Blocked by ai-factory path guard: "' + rel + '" matches forbidden pattern "' + f.g + '" (CLAUDE.md -> "All agents must NOT edit"). Edit .factory.yaml and re-run factory install if this is intentional.');
    process.exit(2);
  }
}

if (allow !== null) {
  const ok = allow.some((a) => a.re.test(rel));
  if (!ok) {
    const list = allow.map((a) => a.g).join(", ") || "(none)";
    console.error('Blocked by ai-factory path guard: "' + rel + '" is outside ' + agentName + ' allowed paths [' + list + '] (CLAUDE.md -> "Path scoping for agents"). Edit .factory.yaml and re-run factory install if this is intentional.');
    process.exit(2);
  }
}

process.exit(0);
